    out=[[0]*W for _ in range(H)]
    tc={j:g[0][j] for j,v in enumerate(g[0]) if v}
    bars=sorted(tc)
    byc=defaultdict(list)
    for r in range(1,H):
        for c in range(W):
            if g[r][c]: byc[g[r][c]].append((r,c))
    # verticals: bar from row 0 down to max dot row of same color (or bottom)
    for j,v in tc.items():
        end=max((rr for rr,_ in byc.get(v,[])), default=H-1)
        for r in range(end+1): out[r][j]=v
    # horizontals: each dot extends toward its nearest bar (any bar), filled with dot color
    for dv,cells in byc.items():
        for r,c in cells:
            best=min(bars,key=lambda b:abs(b-c))
            lo,hi=(c,best) if c<best else (best,c)
            for cc in range(lo,hi+1): out[r][cc]=dv
    return out

for p in ['Demo pair 1','Demo pair 2']:
    print(p, f(G[p+' input'])==G[p+' output'])
print(json.dumps(f(G['Test input'])))

